// Host words, copied from the web host page (host.html, const T). Keep them in step with the web.
// Generated by copying; hero/hereHero return parts instead of HTML. Screens fill in with these functions.
import { arN, countWord, countWordHost, hostWord } from '../lib/words';
import type { Widen } from './widen';

// every number carries its word: "guest" = one invitation, "person" = one head
const E = (n: number, k: 'person' | 'guest' = 'person') => countWord(n, k, 'en');
// Arabic zero reads «ولا ضيف» / «ولا أحد», not «0 ضيف»
const A = (n: number, k: 'person' | 'guest' = 'person') => countWordHost(n, k, 'ar');

/** The big number line: show `n` big (t-num) when given, else `big` as a bold word; then `w`. */
export type HeroParts = { n?: number; big?: string; w: string };

